const CACHE='covepm-mobile-v2';
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.add('/mobile')));self.skipWaiting();});
self.addEventListener('activate',event=>{event.waitUntil(self.clients.claim());});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET')return;event.respondWith(fetch(event.request).then(response=>{const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy));return response;}).catch(()=>caches.match(event.request)));});
self.addEventListener('push',event=>{let data={title:'CovePM Marketing OS',body:'A new approval is ready.',url:'/mobile',tag:'covepm-approval'};try{data={...data,...event.data.json()};}catch{}event.waitUntil(self.registration.showNotification(data.title,{body:data.body,icon:'/mobile-icon.png',badge:'/mobile-icon.png',data:{url:data.url},tag:data.tag||'covepm-approval'}));});
self.addEventListener('notificationclick',event=>{event.notification.close();event.waitUntil(clients.matchAll({type:'window',includeUncontrolled:true}).then(list=>{const existing=list.find(client=>client.url.includes('/mobile'));if(existing){existing.focus();return existing.navigate('/mobile');}return clients.openWindow(event.notification.data?.url||'/mobile');}));});
